Code
buildQuiz("keeling-curve-quiz", "Check Your Understanding — The Keeling Curve", [
  {
    q: "What causes the zig-zag (seasonal oscillation) pattern visible in the Keeling Curve?",
    options: [
      "A) Measurement errors at the Mauna Loa observatory",
      "B) Volcanic eruptions releasing and absorbing CO₂",
      "C) Seasonal plant growth absorbing CO₂ in spring/summer and releasing it in fall/winter",
      "D) Changes in ocean temperature throughout the year"
    ],
    correct: 2,
    explanation: "The seasonal 'breathing' pattern comes from Northern Hemisphere vegetation: plants absorb CO₂ during the growing season (lowering levels) and release it during decomposition in fall/winter."
  },
  {
    q: "What is the approximate CO₂ level today, and how does it compare to pre-industrial levels (~280 ppm)?",
    options: [
      "A) About 315 ppm — only slightly higher than pre-industrial",
      "B) About 350 ppm — a moderate increase",
      "C) About 420 ppm — roughly 50% higher than pre-industrial",
      "D) About 600 ppm — more than double pre-industrial"
    ],
    correct: 2,
    explanation: "Current CO₂ levels have surpassed 420 ppm, about 50% higher than the pre-industrial baseline of ~280 ppm. This level has not been seen on Earth for millions of years."
  }
])

22.1 Interactive: Earth’s Orbit Distance


Code
Plot = require("@observablehq/plot")

orbitData = [
  {month: "Jan", distance: 147.1, season: "Winter (NH)"},
  {month: "Feb", distance: 147.8, season: "Winter"},
  {month: "Mar", distance: 148.9, season: "Spring"},
  {month: "Apr", distance: 150.0, season: "Spring"},
  {month: "May", distance: 151.0, season: "Spring"},
  {month: "Jun", distance: 151.8, season: "Summer"},
  {month: "Jul", distance: 152.1, season: "Summer (NH)"},
  {month: "Aug", distance: 151.5, season: "Summer"},
  {month: "Sep", distance: 150.5, season: "Fall"},
  {month: "Oct", distance: 149.3, season: "Fall"},
  {month: "Nov", distance: 148.1, season: "Fall"},
  {month: "Dec", distance: 147.3, season: "Winter"}
]

Plot.plot({
  title: "Earth-Sun Distance Throughout the Year",
  subtitle: "Distance in millions of kilometers",
  width: 650,
  height: 350,
  x: {label: "Month", domain: orbitData.map(d =&gt; d.month)},
  y: {label: "Distance (million km)", domain: [146, 153]},
  marks: [
    Plot.line(orbitData, {x: "month", y: "distance", stroke: "#e67e22", strokeWidth: 3,
        tip: true}),
    Plot.dot(orbitData, {x: "month", y: "distance", fill: "#e67e22", r: 6,
        tip: true}),
    Plot.text([{month: "Jan", distance: 147.1}], {x: "month", y: "distance", text: d =&gt; "Closest!", dy: -15, fill: "red", fontWeight: "bold"}),
    Plot.text([{month: "Jul", distance: 152.1}], {x: "month", y: "distance", text: d =&gt; "Farthest!", dy: -15, fill: "blue", fontWeight: "bold"})
  ]
})

























