24.1.1 🔵 Cycle 1: ECCENTRICITY (~100,000 years)
THE STRETCH: Earth’s orbit changes from nearly circular ⭕ to more elliptical 🥚


Code
viewof eccentricity = Inputs.range([0, 0.06], {
  step: 0.005,
  value: 0.017,
  label: "Eccentricity (current = 0.017):"
})









Code
// Draw orbit with variable eccentricity
{
  const width = 500;
  const height = 400;
  const cx = width / 2;
  const cy = height / 2;
  const a = 180; // semi-major axis
  const b = a * Math.sqrt(1 - eccentricity * eccentricity); // semi-minor axis
  const c = a * eccentricity; // focal distance

  const svg = d3.create("svg")
    .attr("width", width)
    .attr("height", height);

  // Draw orbit ellipse
  svg.append("ellipse")
    .attr("cx", cx + c)
    .attr("cy", cy)
    .attr("rx", a)
    .attr("ry", b)
    .attr("fill", "none")
    .attr("stroke", "#3498db")
    .attr("stroke-width", 2);

  // Draw Sun at one focus
  svg.append("circle")
    .attr("cx", cx)
    .attr("cy", cy)
    .attr("r", 20)
    .attr("fill", "#f1c40f");

  svg.append("text")
    .attr("x", cx)
    .attr("y", cy + 5)
    .attr("text-anchor", "middle")
    .attr("font-size", "12px")
    .text("☀️");

  // Draw Earth positions
  svg.append("circle")
    .attr("cx", cx + c + a)
    .attr("cy", cy)
    .attr("r", 10)
    .attr("fill", "#3498db");

  svg.append("text")
    .attr("x", cx + c + a)
    .attr("y", cy - 20)
    .attr("text-anchor", "middle")
    .attr("font-size", "10px")
    .text("Aphelion (farthest)");

  svg.append("circle")
    .attr("cx", cx + c - a)
    .attr("cy", cy)
    .attr("r", 10)
    .attr("fill", "#2ecc71");

  svg.append("text")
    .attr("x", cx + c - a)
    .attr("y", cy - 20)
    .attr("text-anchor", "middle")
    .attr("font-size", "10px")
    .text("Perihelion (closest)");

  // Info box
  svg.append("rect")
    .attr("x", 10)
    .attr("y", 10)
    .attr("width", 200)
    .attr("height", 80)
    .attr("fill", "#f5f5f5")
    .attr("rx", 5);

  svg.append("text")
    .attr("x", 20)
    .attr("y", 35)
    .attr("font-size", "12px")
    .text(`Eccentricity: ${eccentricity.toFixed(3)}`);

  const distDiff = ((2 * a * eccentricity) / a * 100).toFixed(1);
  svg.append("text")
    .attr("x", 20)
    .attr("y", 55)
    .attr("font-size", "12px")
    .text(`Distance variation: ${distDiff}%`);

  svg.append("text")
    .attr("x", 20)
    .attr("y", 75)
    .attr("font-size", "11px")
    .attr("fill", "#666")
    .text(`Cycle: ~100,000 years`);

  return svg.node();
}









