24.1.2 🌐 Cycle 2: OBLIQUITY (Axial Tilt) (~41,000 years)
THE WOBBLE: Earth doesn’t spin perfectly upright! Our axial tilt changes between 22.1° and 24.5° — affecting how extreme our seasons are! 🎿❄️🏖️


Code
viewof tiltAngle = Inputs.range([22.1, 24.5], {
  step: 0.1,
  value: 23.5,
  label: "Axial Tilt (current = 23.5°):"
})









Code
{
  const width = 500;
  const height = 350;

  const svg = d3.create("svg")
    .attr("width", width)
    .attr("height", height);

  // Draw orbital plane
  svg.append("line")
    .attr("x1", 50)
    .attr("y1", height/2)
    .attr("x2", width - 50)
    .attr("y2", height/2)
    .attr("stroke", "#ccc")
    .attr("stroke-width", 2)
    .attr("stroke-dasharray", "5,5");

  svg.append("text")
    .attr("x", width - 100)
    .attr("y", height/2 + 20)
    .attr("font-size", "11px")
    .attr("fill", "#999")
    .text("Orbital Plane");

  // Draw Earth
  const earthX = width / 2;
  const earthY = height / 2;
  const earthR = 60;

  svg.append("circle")
    .attr("cx", earthX)
    .attr("cy", earthY)
    .attr("r", earthR)
    .attr("fill", "#3498db");

  // Draw tilted axis
  const tiltRad = tiltAngle * Math.PI / 180;
  const axisLength = 120;

  svg.append("line")
    .attr("x1", earthX - axisLength * Math.sin(tiltRad))
    .attr("y1", earthY + axisLength * Math.cos(tiltRad))
    .attr("x2", earthX + axisLength * Math.sin(tiltRad))
    .attr("y2", earthY - axisLength * Math.cos(tiltRad))
    .attr("stroke", "#e74c3c")
    .attr("stroke-width", 3);

  // Angle indicator
  svg.append("text")
    .attr("x", earthX + 70)
    .attr("y", earthY - 80)
    .attr("font-size", "14px")
    .attr("font-weight", "bold")
    .attr("fill", "#e74c3c")
    .text(`${tiltAngle.toFixed(1)}°`);

  // Effect description
  const effect = tiltAngle &gt; 23.5 ? "MORE extreme seasons" : tiltAngle &lt; 23.5 ? "LESS extreme seasons" : "Current tilt";
  svg.append("rect")
    .attr("x", 20)
    .attr("y", 20)
    .attr("width", 180)
    .attr("height", 60)
    .attr("fill", "#f5f5f5")
    .attr("rx", 5);

  svg.append("text")
    .attr("x", 30)
    .attr("y", 45)
    .attr("font-size", "12px")
    .text(`Tilt: ${tiltAngle.toFixed(1)}°`);

  svg.append("text")
    .attr("x", 30)
    .attr("y", 65)
    .attr("font-size", "11px")
    .attr("fill", "#666")
    .text(effect);

  return svg.node();
}









