frontalChart = {
  // 1. Setup Canvas
  const canvas = document.createElement('canvas');
  const WIDTH = 800;
  const HEIGHT = 500;
  canvas.width = WIDTH;
  canvas.height = HEIGHT;
  canvas.style.width = "100%";
  canvas.style.maxWidth = "800px";
  canvas.style.height = "auto";
  canvas.style.border = "1px solid #e2e8f0";
  canvas.style.borderRadius = "0.5rem";
  canvas.style.backgroundColor = "#fff";

  const ctx = canvas.getContext('2d');

  // 2. Constants & Helpers
  const lerp = (a, b, t) =&gt; a + (b - a) * t;

  const drawCurvedArrow = (ctx, startX, startY, cpX, cpY, endX, endY, color) =&gt; {
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.quadraticCurveTo(cpX, cpY, endX, endY);
    ctx.strokeStyle = color;
    ctx.lineWidth = 4;
    ctx.stroke();

    // arrowhead
    const angle = Math.atan2(endY - cpY, endX - cpX);
    ctx.save();
    ctx.translate(endX, endY);
    ctx.rotate(angle);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(-12, -7);
    ctx.lineTo(-12, 7);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.restore();
  };

  const drawCloud = (ctx, x, y, progress) =&gt; {
    if (progress &lt;= 5) return;

    // Cloud grows and darkens as progress increases
    const scale = Math.min(1.2, progress / 40);
    const darkness = Math.max(0, (progress - 40) / 60); 

    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);

    const r = 255 - darkness * 120;
    const g = 255 - darkness * 120;
    const b = 255 - darkness * 110;
    ctx.fillStyle = `rgba(${r}, ${g}, ${b}, ${Math.min(0.9, scale)})`;

    ctx.beginPath();
    ctx.arc(0, 0, 45, 0, Math.PI * 2);
    ctx.arc(-35, 10, 35, 0, Math.PI * 2);
    ctx.arc(35, 10, 35, 0, Math.PI * 2);
    ctx.arc(-20, -25, 40, 0, Math.PI * 2);
    ctx.arc(20, -25, 40, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  };

  // 3. Particle System State
  const createParticles = (count, isWater = false) =&gt; Array.from({ length: count }, () =&gt; ({
    x: Math.random() * 120 + 5,
    y: Math.random() * 120 + 5,
    vx: (Math.random() - 0.5) * 2,
    vy: (Math.random() - 0.5) * 2,
    isWater
  }));

  const coldParticles = createParticles(180, false); // Dense, no water
  const warmParticles = [...createParticles(70, false), ...createParticles(40, true)]; // Less dense, holds water vapor
  const cloudParticles = [...createParticles(70, false), ...createParticles(40, true)]; // Will cool and condense

  const raindrops = Array.from({length: 120}, () =&gt; ({
    x: Math.random() * 120, 
    y: Math.random() * 400,
    speed: Math.random() * 4 + 6
  }));

  let animationFrameId;

  // 4. Main Animation Loop
  function render() {
    const progress = viewof frontProgress.value;
    const cloudX = frontX - 80;
    const cloudY = 150;

    // --- Draw Sky ---
    const skyGradient = ctx.createLinearGradient(0, 0, 0, 450);
    skyGradient.addColorStop(0, '#bae6fd');
    skyGradient.addColorStop(1, '#e0f2fe');
    ctx.fillStyle = skyGradient;
    ctx.fillRect(0, 0, WIDTH, HEIGHT);

    // --- Draw Ground ---
    ctx.fillStyle = '#22c55e';
    ctx.fillRect(0, 450, WIDTH, 50);
    ctx.strokeStyle = '#166534';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0, 450);
    ctx.lineTo(WIDTH, 450);
    ctx.stroke();

    // --- Draw Warm Air Mass Background ---
    ctx.fillStyle = 'rgba(239, 68, 68, 0.05)';
    ctx.beginPath();
    ctx.moveTo(frontX, 450);
    ctx.lineTo(frontX - 250, 100);
    ctx.lineTo(WIDTH, 100);
    ctx.lineTo(WIDTH, 450);
    ctx.fill();

    // --- Draw Cold Air Wedge ---
    ctx.fillStyle = 'rgba(59, 130, 246, 0.25)';
    ctx.beginPath();
    ctx.moveTo(0, 450);
    ctx.lineTo(frontX, 450);
    ctx.lineTo(frontX - 250, 100);
    ctx.lineTo(0, 100);
    ctx.closePath();
    ctx.fill();

    // Front Boundary Line
    ctx.strokeStyle = '#2563eb';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(frontX, 450);
    ctx.lineTo(frontX - 250, 100);
    ctx.stroke();

    // --- Draw Text Labels ---
    ctx.fillStyle = '#1e3a8a';
    ctx.font = 'bold 18px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText("Cold, Dry Air", Math.max(80, frontX - 180), 400);

    ctx.fillStyle = '#991b1b';
    ctx.fillText("Warm, Moist Air", Math.min(WIDTH - 100, frontX + 120), 400);

    // --- Draw Wind Arrows (Rising Warm Air) ---
    if (progress &gt; 5) {
      drawCurvedArrow(ctx, frontX + 30, 420, frontX - 20, 300, frontX - 80, 200, 'rgba(239, 68, 68, 0.7)');
      drawCurvedArrow(ctx, frontX + 90, 420, frontX + 40, 300, frontX - 20, 200, 'rgba(239, 68, 68, 0.7)');
    }

    // --- Draw Cloud ---
    drawCloud(ctx, cloudX, cloudY, progress);

    // --- Draw Rain ---
    if (progress &gt; 50) {
      const rainIntensity = (progress - 50) / 50;
      ctx.strokeStyle = 'rgba(37, 99, 235, 0.6)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      raindrops.forEach((r, i) =&gt; {
        if (i &gt; rainIntensity * 120) return;

        let actualX = cloudX - 60 + r.x; 
        let actualY = cloudY + 30 + r.y;

        if (actualY &gt; 450) {
            r.y = 0;
            r.x = Math.random() * 120;
        } else {
            ctx.moveTo(actualX, actualY);
            ctx.lineTo(actualX - 4, actualY + 12);
            r.y += r.speed;
            r.x -= 1; // Slight angle leftwards
        }
      });
      ctx.stroke();
    }

    // --- Draw Magnifying Particle Boxes ---
    const drawBox = (boxX, boxY, targetX, targetY, title, temp, particlesArr, isCloudBox = false) =&gt; {
      const boxSize = 130;

      // Target Lines
      ctx.beginPath();
      ctx.moveTo(boxX + boxSize/2, boxY + boxSize/2);
      ctx.lineTo(targetX, targetY);
      ctx.strokeStyle = 'rgba(0,0,0,0.3)';
      ctx.setLineDash([4, 4]);
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.setLineDash([]);

      // Box Background
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(boxX, boxY, boxSize, boxSize);
      ctx.strokeStyle = '#334155';
      ctx.lineWidth = 3;
      ctx.strokeRect(boxX, boxY, boxSize, boxSize);

      // Title
      ctx.fillStyle = '#0f172a';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(title, boxX + boxSize/2, boxY - 8);

      // Particle Physics
      const speedMultiplier = Math.max(0.1, 0.2 + (temp / 100) * 1.5);
      const clumping = isCloudBox ? Math.max(0, (progress - 30) / 70) : 0; 

      for (let i = 0; i &lt; particlesArr.length; i++) {
        const p = particlesArr[i];

        if (p.isWater && isCloudBox) {
            // Water molecules clump together in the cloud (condensation)
            p.vx += (boxSize/2 - p.x) * clumping * 0.004;
            p.vy += (boxSize/2 - p.y) * clumping * 0.004;
            p.x += p.vx * (1 - clumping * 0.5); 
            p.y += p.vy * (1 - clumping * 0.5);
        } else {
            p.x += p.vx * speedMultiplier;
            p.y += p.vy * speedMultiplier;
        }

        // Bounce off walls
        if (p.x &lt; 4 || p.x &gt; boxSize - 4) p.vx *= -1;
        if (p.y &lt; 4 || p.y &gt; boxSize - 4) p.vy *= -1;

        // Clamp bounds
        p.x = Math.max(4, Math.min(boxSize - 4, p.x));
        p.y = Math.max(4, Math.min(boxSize - 4, p.y));

        // Render Particle
        ctx.beginPath();
        ctx.arc(boxX + p.x, boxY + p.y, p.isWater ? 4 : 2.5, 0, Math.PI * 2);

        if (p.isWater) {
             const grad = ctx.createRadialGradient(boxX + p.x, boxY + p.y, 0, boxX + p.x, boxY + p.y, 4);
             grad.addColorStop(0, '#93c5fd'); 
             grad.addColorStop(1, '#2563eb'); 
             ctx.fillStyle = grad;
        } else {
             ctx.fillStyle = '#475569'; 
        }
        ctx.fill();
      }
    };

    const cloudTemp = 80 - (progress * 0.6); // Cools down as it gets pushed higher

    // Left Box (Cold Air Wedge)
    drawBox(20, 300, frontX - 150, 380, "Cold, Dry Air (Dense)", 20, coldParticles);

    // Right Box (Warm Moist Air)
    drawBox(650, 300, frontX + 100, 380, "Warm, Moist Air", 80, warmParticles);

    // Top Box (Rising, Cooling Air / Cloud formation)
    drawBox(335, 10, cloudX, cloudY, "Cooling & Condensing", cloudTemp, cloudParticles, true);

    animationFrameId = requestAnimationFrame(render);
  }

  // 5. Start Animation & Cleanup Handler
  render();
  invalidation.then(() =&gt; cancelAnimationFrame(animationFrameId));

  return canvas;
}









